CREATE COLUMN TABLE "TEST_AP"."OSCP" ("prblmTypID" SMALLINT CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Descriptio" NCLOB MEMORY THRESHOLD 1000, "Active" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("prblmTypID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OSCP_NAME" ON "TEST_AP"."OSCP" ( "Name" ASC )